/** The note nearest a frequency and how far off it is: `{ midi, name, hz, cents }`, `cents` positive when sharp. */
/** A pitch's frequency, A4 at 440 Hz unless told. */
export { cents, midiToHz } from "@audio/note";
export { detectKeys, type KeyNote } from "./key";
export {
  inScale,
  nearestInScale,
  rollScale,
  SCALES,
  type Scale,
  type ScaleName,
  scalePitchClasses,
} from "./scale";

import key from "@audio/mir-key";
import { NAMES_SHARP } from "@audio/note";
import type { Scale } from "./scale";

/** What a key is read from: a note's pitch and how long it lasts, in any unit. A muted note counts for nothing. */
export interface KeyNote {
  length: number;
  muted?: boolean;
  pitch: number;
}

/**
 * The keys `notes` are likeliest in, likeliest first, at most `count`: each
 * pitch class weighed by how long it sounds, against the major and minor key
 * profiles of `@audio/mir-key` (Krumhansl-Schmuckler). `audio` adds the
 * sound of recordings, a weight per pitch class in the same unit as the
 * notes' lengths, such as an `audioChroma` times the seconds it plays. One
 * part alone is often ambiguous, as a bass line is: pass every part of the
 * song. None for no notes and no sound.
 */
export function detectKeys(
  notes: readonly KeyNote[],
  count = 3,
  audio?: readonly number[]
): Scale[] {
  const chroma = Array.from({ length: 12 }, (_, at) => audio?.[at] ?? 0);
  for (const note of notes) {
    if (!note.muted && note.length > 0) {
      const at = ((Math.round(note.pitch) % 12) + 12) % 12;
      chroma[at] = (chroma[at] as number) + note.length;
    }
  }
  // One pitch class alone, or none, correlates with nothing.
  if (chroma.filter((weight) => weight > 0).length < 2) {
    return [];
  }
  return key(chroma)
    .scores.slice(0, count)
    .map(({ label }) => {
      const minor = label.endsWith("m");
      return {
        name: minor ? "minor" : "major",
        root: NAMES_SHARP.indexOf(minor ? label.slice(0, -1) : label),
      } satisfies Scale;
    });
}

/**
 * Scales on a root: which pitch classes a scale keeps. The steps of most come
 * from `@audio/note`, with the three church modes it does not list added; the
 * snapping is its `snapMidi`.
 */

import { SCALES as NOTE_SCALES, snapMidi } from "@audio/note";

/** A scale as a piano roll reads it: its pitch classes and its root. */
export interface RollScale {
  pitchClasses: readonly number[];
  root: number;
}

/** The steps of each scale, as semitones above the root. */
export const SCALES = {
  ...NOTE_SCALES,
  locrian: [0, 1, 3, 5, 6, 8, 10],
  lydian: [0, 2, 4, 6, 7, 9, 11],
  phrygian: [0, 1, 3, 5, 7, 8, 10],
} as const satisfies Record<string, readonly number[]>;

/** The name of a scale of `SCALES`. */
export type ScaleName = keyof typeof SCALES;

/** A scale on a root: C major is `{ name: "major", root: 0 }`. */
export interface Scale {
  name: ScaleName;
  /** The pitch class it starts on: 0 is C, 11 is B. */
  root: number;
}

const pitchClass = (pitch: number) => ((Math.round(pitch) % 12) + 12) % 12;

/** The pitch classes a scale keeps, from 0 (C) to 11 (B), in order. */
export function scalePitchClasses({ name, root }: Scale): number[] {
  return SCALES[name]
    .map((step) => pitchClass(root + step))
    .sort((a, b) => a - b);
}

/** Whether a MIDI pitch is in a scale. */
export function inScale(pitch: number, scale: Scale): boolean {
  return scalePitchClasses(scale).includes(pitchClass(pitch));
}

/**
 * The pitch in a scale nearest `pitch`: itself when it is in it, else the
 * nearest one, the lower of two as near.
 */
export function nearestInScale(pitch: number, scale: Scale): number {
  return snapMidi(Math.round(pitch), {
    root: scale.root,
    scale: SCALES[scale.name],
  });
}

/** A scale as a piano roll reads it: its pitch classes and its root. */
export function rollScale(scale: Scale): RollScale {
  return { pitchClasses: scalePitchClasses(scale), root: scale.root };
}
